import React, { useState, useCallback } from 'react';
import { Calendar, ButtonGroup, Button, Stack } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
  initialDate?: Date;
}

const startOfDay = (date: Date): Date => {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
};

const addDays = (date: Date, days: number): Date => {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
};

const isSameDay = (a: Date, b: Date): boolean =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

const ReportDatePicker: React.FC<ReportDatePickerProps> = ({
  onChange,
  initialDate,
}) => {
  const [selectedDate, setSelectedDate] = useState<Date>(
    startOfDay(initialDate ?? new Date())
  );

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const handleSelect = useCallback(
    (date: Date) => {
      const normalized = startOfDay(date);
      setSelectedDate(normalized);
      onChange?.(normalized);
    },
    [onChange]
  );

  const quickOptions: Array<{ label: string; value: Date }> = [
    { label: 'Сегодня', value: today },
    { label: 'Вчера', value: yesterday },
    { label: 'Неделя назад', value: weekAgo },
  ];

  return (
    <Stack direction="column" gap="jx-space-3" className="jx-surface jx-p-4 jx-rounded-md">
      <ButtonGroup aria-label="Быстрый выбор даты отчёта">
        {quickOptions.map((option) => (
          <Button
            key={option.label}
            variant={isSameDay(selectedDate, option.value) ? 'primary' : 'secondary'}
            size="sm"
            onClick={() => handleSelect(option.value)}
          >
            {option.label}
          </Button>
        ))}
      </ButtonGroup>

      <Calendar
        mode="single"
        selected={selectedDate}
        defaultMonth={selectedDate}
        onSelect={(date: Date | undefined) => {
          if (date) {
            handleSelect(date);
          }
        }}
        className="jx-calendar"
      />
    </Stack>
  );
};

export default ReportDatePicker;

